<?php
namespace App\Services\FrontDesk;
use App\Enums\{ReservationStatus,RoomStatus}; use App\Models\{Reservation,Stay}; use App\Services\Folios\FolioService; use Illuminate\Support\Facades\DB;
class CheckInService { public function __construct(private FolioService $folios){} public function execute(Reservation $reservation,int $userId):Stay { return DB::transaction(function()use($reservation,$userId){$reservation->load('rooms.room'); abort_if($reservation->status===ReservationStatus::CheckedIn,422,'Reservation is already checked in.'); $rr=$reservation->rooms->first(); abort_unless($rr && $rr->room,422,'Assign a room before check-in.'); abort_if(Stay::where('room_id',$rr->room_id)->where('status','in_house')->exists(),422,'This room is already occupied.'); $stay=Stay::create(['property_id'=>$reservation->property_id,'reservation_id'=>$reservation->id,'guest_id'=>$reservation->guest_id,'room_id'=>$rr->room_id,'checked_in_at'=>now(),'expected_check_out_at'=>$reservation->check_out_at,'status'=>'in_house','checked_in_by'=>$userId]); $reservation->update(['status'=>ReservationStatus::CheckedIn]); $rr->room->update(['status'=>RoomStatus::Occupied]); $folio=$this->folios->ensureForReservation($reservation,$stay); if(!$folio->stay_id)$folio->update(['stay_id'=>$stay->id]); $this->folios->postRoomCharges($reservation,$folio,$userId); return $stay;}); } }
